# class-free prototypes, subset-only
def mean(data):
    d = list(data)
    if not d:
        raise ValueError("mean requires at least one data point")
    return sum(d) / len(d)

def median(data):
    d = sorted(data)
    n = len(d)
    if n == 0:
        raise ValueError("no median for empty data")
    if n % 2 == 1:
        return d[n // 2]
    return (d[n // 2 - 1] + d[n // 2]) / 2

def product(*pools, **kw):
    repeat = kw.get("repeat", 1)
    pools = [list(p) for p in pools] * repeat
    result = [[]]
    for pool in pools:
        result = [r + [x] for r in result for x in pool]
    return [tuple(r) for r in result]

def combinations(iterable, r):
    pool = list(iterable)
    n = len(pool)
    out = []
    if r > n:
        return out
    idx = list(range(r))
    out.append(tuple([pool[i] for i in idx]))
    while True:
        i = r - 1
        while i >= 0 and idx[i] == i + n - r:
            i -= 1
        if i < 0:
            return out
        idx[i] += 1
        for j in range(i + 1, r):
            idx[j] = idx[j - 1] + 1
        out.append(tuple([pool[k] for k in idx]))

def hexlify(b):
    return b.hex().encode()

def unhexlify(s):
    if isinstance(s, str):
        s = s.encode()
    return bytes([int(s[i:i+2].decode(), 16) for i in range(0, len(s), 2)])

def _pack_one(fmt, v, big):
    n = {"B": 1, "H": 2, "I": 4, "Q": 8}[fmt]
    order = "big" if big else "little"
    return v.to_bytes(n, order)

def pack(fmt, *vals):
    big = fmt[0] in (">", "!")
    body = fmt[1:] if fmt[0] in ("<", ">", "!", "=", "@") else fmt
    out = b""
    i = 0
    for ch in body:
        out += _pack_one(ch, vals[i], big)
        i += 1
    return out

def unpack(fmt, data):
    big = fmt[0] in (">", "!")
    body = fmt[1:] if fmt[0] in ("<", ">", "!", "=", "@") else fmt
    order = "big" if big else "little"
    out = []
    pos = 0
    for ch in body:
        n = {"B": 1, "H": 2, "I": 4, "Q": 8}[ch]
        out.append(int.from_bytes(data[pos:pos+n], order))
        pos += n
    return tuple(out)

def bisect_left(a, x):
    lo = 0
    hi = len(a)
    while lo < hi:
        mid = (lo + hi) // 2
        if a[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

def unescape(s):
    named = {"&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&#39;": "'", "&nbsp;": " "}
    for k in named:
        s = s.replace(k, named[k])
    return s

